import { useRef, useState } from 'react';
import { TableDispatch } from 'react-table';

import { DEFAULT_VARIANT_CONFIG } from '../DataTable/constants.js';
import { useColumnsSizesActions } from '../plugins/use-column-sizes/actions.js';
import { TableVariantConfig } from '../types/shared-table-types.js';

function didVariantChange(prev: TableVariantConfig, next: TableVariantConfig) {
  return (
    Object.keys(prev).length !== Object.keys(next).length ||
    Object.entries(prev).some(([key, value]) => next[key] !== value)
  );
}

/**
 * To avoid unnecessary re-renders, this function checks if the variant actually changed before updating to a new value.
 * If no variant was set on the table, the default configuration is used.
 *
 * @param variantProp - variant prop passed to the DataTable
 * @param dispatch - table dispatch fn
 * @returns - updated table variant config, setter for updating the table variant
 */
export function useTableVariant(
  variantProp: TableVariantConfig | 'default',
  dispatch: TableDispatch,
): [
  TableVariantConfig,
  React.Dispatch<React.SetStateAction<TableVariantConfig>>,
] {
  const actualVariantFromProp =
    variantProp === 'default'
      ? { ...DEFAULT_VARIANT_CONFIG }
      : { ...DEFAULT_VARIANT_CONFIG, ...variantProp };

  const externalTableVariantRef = useRef<TableVariantConfig>(
    actualVariantFromProp,
  );
  const [tableVariant, setTableVariant] = useState<TableVariantConfig>(
    externalTableVariantRef.current,
  );

  if (
    didVariantChange(actualVariantFromProp, externalTableVariantRef.current)
  ) {
    const nextVariant = actualVariantFromProp;
    if (nextVariant.rowDensity !== tableVariant.rowDensity) {
      dispatch({ type: useColumnsSizesActions.rowDensityChanged });
    }
    setTableVariant(nextVariant);
    externalTableVariantRef.current = nextVariant;
  }

  return [tableVariant, setTableVariant];
}
